import React, { useState, useEffect } from 'react';
import { 
  validateAmount, 
  validateRecipient, 
  calculateFee, 
  formatCurrency 
} from '../../../utils/transactionHelpers';
import { CURRENCIES, ERROR_MESSAGES } from '../../../constants/transactionConstants';
import transactionService from '../../../services/transactionService';
import './SendMoneyForm.css';

const SendMoneyForm = ({ onSuccess }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    recipient: {
      name: '',
      accountNumber: '',
      bankName: '',
      swiftCode: ''
    },
    amount: '',
    currency: 'USD',
    description: ''
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [fee, setFee] = useState(0);
  const [exchangeRate, setExchangeRate] = useState(1);
  const [confirmation, setConfirmation] = useState(false);

  useEffect(() => {
    if (formData.amount && formData.currency) {
      calculateTransactionFee();
    }
  }, [formData.amount, formData.currency]);

  const calculateTransactionFee = async () => {
    try {
      const feeResult = await transactionService.calculateFee(
        formData.amount,
        formData.currency,
        'transfer'
      );
      setFee(feeResult.fee);
      setExchangeRate(feeResult.exchangeRate || 1);
    } catch (err) {
      console.error('Error calculating fee:', err);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    if (name.includes('.')) {
      const [parent, child] = name.split('.');
      setFormData(prev => ({
        ...prev,
        [parent]: {
          ...prev[parent],
          [child]: value
        }
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        [name]: value
      }));
    }
    setError(null);
  };

  const validateStep = () => {
    switch (step) {
      case 1:
        const recipientValidation = validateRecipient(formData.recipient);
        if (!recipientValidation.isValid) {
          setError(Object.values(recipientValidation.errors)[0]);
          return false;
        }
        break;
      case 2:
        const amountValidation = validateAmount(formData.amount, formData.currency);
        if (!amountValidation.isValid) {
          setError(amountValidation.error);
          return false;
        }
        break;
      default:
        return true;
    }
    return true;
  };

  const handleNext = () => {
    if (validateStep()) {
      setStep(prev => prev + 1);
      setError(null);
    }
  };

  const handleBack = () => {
    setStep(prev => prev - 1);
    setError(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!confirmation) {
      setError('Please confirm the transaction details');
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const result = await transactionService.sendMoney({
        ...formData,
        fee,
        exchangeRate
      });

      onSuccess?.(result);
    } catch (err) {
      setError(err.message || ERROR_MESSAGES.TRANSACTION_FAILED);
    } finally {
      setLoading(false);
    }
  };

  const renderStepContent = () => {
    switch (step) {
      case 1:
        return (
          <div className="form-step recipient-details">
            <h3>Recipient Details</h3>
            <div className="form-group">
              <label>Recipient Name</label>
              <input
                type="text"
                name="recipient.name"
                value={formData.recipient.name}
                onChange={handleInputChange}
                placeholder="Enter recipient's full name"
              />
            </div>
            <div className="form-group">
              <label>Account Number</label>
              <input
                type="text"
                name="recipient.accountNumber"
                value={formData.recipient.accountNumber}
                onChange={handleInputChange}
                placeholder="Enter account number"
              />
            </div>
            <div className="form-group">
              <label>Bank Name</label>
              <input
                type="text"
                name="recipient.bankName"
                value={formData.recipient.bankName}
                onChange={handleInputChange}
                placeholder="Enter bank name"
              />
            </div>
            <div className="form-group">
              <label>SWIFT/BIC Code</label>
              <input
                type="text"
                name="recipient.swiftCode"
                value={formData.recipient.swiftCode}
                onChange={handleInputChange}
                placeholder="Enter SWIFT/BIC code"
              />
            </div>
          </div>
        );

      case 2:
        return (
          <div className="form-step amount-details">
            <h3>Amount Details</h3>
            <div className="form-group">
              <label>Amount</label>
              <div className="amount-input">
                <input
                  type="number"
                  name="amount"
                  value={formData.amount}
                  onChange={handleInputChange}
                  placeholder="Enter amount"
                />
                <select
                  name="currency"
                  value={formData.currency}
                  onChange={handleInputChange}
                >
                  {Object.entries(CURRENCIES).map(([code, currency]) => (
                    <option key={code} value={code}>
                      {code} - {currency.name}
                    </option>
                  ))}
                </select>
              </div>
            </div>
            <div className="form-group">
              <label>Description (Optional)</label>
              <textarea
                name="description"
                value={formData.description}
                onChange={handleInputChange}
                placeholder="Enter transfer description"
              />
            </div>
          </div>
        );

      case 3:
        return (
          <div className="form-step confirmation">
            <h3>Confirm Transaction</h3>
            <div className="confirmation-details">
              <div className="detail-item">
                <span>Recipient:</span>
                <span>{formData.recipient.name}</span>
              </div>
              <div className="detail-item">
                <span>Amount:</span>
                <span>{formatCurrency(formData.amount, formData.currency)}</span>
              </div>
              <div className="detail-item">
                <span>Fee:</span>
                <span>{formatCurrency(fee, formData.currency)}</span>
              </div>
              <div className="detail-item">
                <span>Total:</span>
                <span>{formatCurrency(Number(formData.amount) + fee, formData.currency)}</span>
              </div>
              <div className="confirmation-checkbox">
                <input
                  type="checkbox"
                  id="confirm"
                  checked={confirmation}
                  onChange={(e) => setConfirmation(e.target.checked)}
                />
                <label htmlFor="confirm">
                  I confirm that all details are correct
                </label>
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="send-money-form">
      <div className="progress-bar">
        {[1, 2, 3].map((stepNumber) => (
          <div
            key={stepNumber}
            className={`progress-step ${step >= stepNumber ? 'active' : ''}`}
          >
            {stepNumber}
          </div>
        ))}
      </div>

      <form onSubmit={handleSubmit}>
        {renderStepContent()}

        {error && <div className="error-message">{error}</div>}

        <div className="form-actions">
          {step > 1 && (
            <button
              type="button"
              onClick={handleBack}
              className="back-button"
              disabled={loading}
            >
              Back
            </button>
          )}

          {step < 3 ? (
            <button
              type="button"
              onClick={handleNext}
              className="next-button"
              disabled={loading}
            >
              Next
            </button>
          ) : (
            <button
              type="submit"
              className="submit-button"
              disabled={loading || !confirmation}
            >
              {loading ? 'Processing...' : 'Send Money'}
            </button>
          )}
        </div>
      </form>
    </div>
  );
};

export default SendMoneyForm;
